// Phone wallet route sheet. MetaMask Mobile's WalletConnect can stop answering
// entirely (2026-10-16: it opened with no prompt for this site AND Uniswap,
// for transactions and brand-new pairings alike), while MetaMask's own phone
// link (MetaMask Connect, what Uniswap's "MetaMask" button uses) and its
// in-app browser both keep working. The sheet offers those routes before
// connecting and again when a WalletConnect wallet stops answering.

import { CHAIN } from './chain-config.js';

const SHEET_ID = 'wallet-route-sheet';
// The no-wallet route: a test wallet kept in this browser on testnets
// (device-wallet.js), Coinbase Smart Wallet's passkey on mainnet.
const MAINNET = Number(CHAIN.id) === 1;
const CREATE_LABEL = MAINNET ? 'NO WALLET? CREATE ONE WITH A PASSKEY' : 'NO WALLET? PLAY WITH A TEST WALLET';

/**
 * A link that opens this page in MetaMask's in-app browser. Android gets an
 * intent URL naming the app package: Chrome sent the universal link to the
 * Play Store listing instead (2026-10-16), whose OPEN button only launches the
 * wallet home and drops the page. iOS keeps the universal link.
 */
export function metamaskDappLink(loc = globalThis.location, userAgent = globalThis.navigator?.userAgent) {
  const host = String(loc?.host || '');
  const params = new URLSearchParams(String(loc?.search || ''));
  params.delete('wcdebug');
  const query = params.toString();
  const target = `${host}${loc?.pathname || '/'}${query ? `?${query}` : ''}`;
  if (/Android/i.test(String(userAgent || ''))) {
    return `intent://dapp/${target}#Intent;scheme=metamask;package=io.metamask;end`;
  }
  return `https://metamask.app.link/dapp/${target}`;
}

export function openInMetaMask() {
  try { globalThis.location.assign(metamaskDappLink()); } catch (_e) { /* headless */ }
}

// Phone review 2026-10-18 (Pixel 9): inside MetaMask's browser the wallet is
// injected, so connecting is one approval and a 1-ticket buy confirmed in ~7 s
// with no app switching. Every Chrome-to-MetaMask route (MetaMask Connect,
// MetaMask over WalletConnect) bounced through a chooser and dropped requests
// with no prompt, and would bounce again on every purchase. The in-app browser
// therefore leads on phones; connecting from this browser stays as a link.
const COPY = {
  connect: {
    title: 'CONNECT ON THIS PHONE',
    body: "Open this site in MetaMask's browser. You approve once, and buys confirm in seconds without switching apps.",
    primary: 'OPEN IN METAMASK',
    primaryRoute: 'metamask',
    secondary: 'OTHER WALLET (WALLETCONNECT)',
    secondaryRoute: 'walletconnect',
    link: 'CONNECT METAMASK FROM THIS BROWSER',
    linkRoute: 'metamask-connect',
  },
  // MetaMask Connect needs the page alive while MetaMask shows the approval;
  // Android Chrome pauses the page about five seconds after the switch, and
  // on 2026-10-18 MetaMask dropped the request with no prompt (live and dev).
  // Its in-app browser needs no handoff at all, so it leads here.
  'metamask-failed': {
    title: "METAMASK DIDN'T CONNECT",
    body: "If MetaMask never asked you to approve, open this site inside MetaMask's browser. It connects there without switching apps.",
    primary: "OPEN IN METAMASK'S BROWSER",
    primaryRoute: 'metamask',
    secondary: 'OTHER WALLET (WALLETCONNECT)',
    secondaryRoute: 'walletconnect',
    link: 'TRY METAMASK AGAIN',
    linkRoute: 'metamask-connect',
  },
  // A computer with no wallet extension used to end at an install prompt.
  'no-wallet': {
    title: 'CONNECT A WALLET',
    body: MAINNET
      ? 'No wallet extension found in this browser. Create a wallet with a passkey in seconds, or connect a phone wallet with a QR code.'
      : 'No wallet extension found in this browser. Play with a free test wallet kept in this browser, or connect a phone wallet with a QR code.',
    primary: MAINNET ? 'CREATE A WALLET WITH A PASSKEY' : 'PLAY WITH A TEST WALLET',
    primaryRoute: 'smart-wallet',
    secondary: 'PHONE WALLET (WALLETCONNECT)',
    secondaryRoute: 'walletconnect',
    link: '',
  },
  silent: {
    title: "YOUR WALLET DIDN'T ANSWER",
    body: "Its WalletConnect link is not responding. With MetaMask, this site works inside MetaMask's browser without that link.",
    primary: 'OPEN IN METAMASK',
    primaryRoute: 'metamask',
    secondary: 'RECONNECT WALLETCONNECT',
    secondaryRoute: 'reconnect',
    link: 'CONNECT METAMASK DIRECTLY',
    linkRoute: 'metamask-connect',
  },
};

/**
 * Show the route sheet. Resolves 'metamask-connect', 'smart-wallet', the
 * mode's secondary route ('walletconnect' or 'reconnect'), 'metamask' (after
 * starting the navigation into MetaMask's browser), or null when closed.
 */
export function chooseMobileWalletRoute(mode = 'connect') {
  const doc = globalThis.document;
  const copy = COPY[mode] || COPY.connect;
  // Without a page to draw on, connect modes fall through to WalletConnect;
  // the no-wallet sheet has nothing to fall back to and connects nothing.
  if (!doc?.body) return Promise.resolve(mode === 'no-wallet' ? null : copy.secondaryRoute);
  doc.getElementById(SHEET_ID)?.remove();
  return new Promise((resolve) => {
    const sheet = doc.createElement('div');
    sheet.id = SHEET_ID;
    sheet.className = 'wallet-route-sheet';
    sheet.setAttribute('role', 'dialog');
    sheet.setAttribute('aria-modal', 'true');
    sheet.setAttribute('aria-labelledby', `${SHEET_ID}-title`);
    sheet.innerHTML = `
      <button type="button" class="wallet-route-sheet__backdrop" data-route="close" aria-label="Close"></button>
      <section class="wallet-route-sheet__card">
        <strong id="${SHEET_ID}-title"></strong>
        <p></p>
        <button type="button" class="wallet-route-sheet__primary" data-route="${copy.primaryRoute || 'metamask-connect'}"></button>
        <button type="button" class="wallet-route-sheet__secondary" data-route="${copy.secondaryRoute}"></button>
        <button type="button" class="wallet-route-sheet__link" data-route="${copy.linkRoute || 'metamask'}"></button>
        <button type="button" class="wallet-route-sheet__create" data-route="smart-wallet">${CREATE_LABEL}</button>
        <button type="button" class="wallet-route-sheet__close" data-route="close">NOT NOW</button>
      </section>`;
    sheet.querySelector('strong').textContent = copy.title;
    // Android Chrome puts a "Chrome or MetaMask?" chooser in front of every
    // jump into MetaMask (2026-10-18, Pixel 9; Rabby opens directly). Say so
    // before the player meets it, or "Chrome" looks like the right answer.
    const android = /Android/i.test(String(globalThis.navigator?.userAgent || ''));
    sheet.querySelector('p').textContent = android && mode !== 'silent' && mode !== 'no-wallet'
      ? `${copy.body} If Android asks which app to open, pick MetaMask.`
      : copy.body;
    sheet.querySelector('.wallet-route-sheet__primary').textContent = copy.primary;
    sheet.querySelector('.wallet-route-sheet__secondary').textContent = copy.secondary;
    const link = sheet.querySelector('.wallet-route-sheet__link');
    if (copy.link === '') link.remove();
    else link.textContent = copy.link || "OPEN THIS SITE IN METAMASK'S BROWSER";
    // The passkey wallet is the fallback for players with no wallet; a mode
    // that already leads with it does not repeat it.
    if (copy.primaryRoute === 'smart-wallet' || mode === 'silent') sheet.querySelector('.wallet-route-sheet__create').remove();
    const finish = (route) => {
      sheet.remove();
      if (route === 'metamask') openInMetaMask();
      resolve(route === 'close' ? null : route);
    };
    sheet.addEventListener('click', (event) => {
      const route = event.target?.closest?.('[data-route]')?.dataset.route;
      if (route) finish(route);
    });
    sheet.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') finish('close');
    });
    doc.body.appendChild(sheet);
    try { sheet.querySelector('.wallet-route-sheet__primary').focus({ preventScroll: true }); } catch (_e) { /* headless */ }
  });
}
